#!/usr/bin/env bash
# Two improvements to Dev Files:
#
#  1. File listing is now grouped by folder (collapsible sections, e.g.
#     "app/templates/instances/" as its own group) instead of one flat
#     table — that stopped being usable once app/ brought the file count
#     from ~18 to 139+. A filter box narrows by path and auto-expands
#     just the matching groups.
#
#  2. Zip upload now diffs against what's already on disk BEFORE writing
#     anything: only files that actually differ (byte-for-byte) are
#     written, backed up, or logged. Re-uploading a zip where you only
#     changed two files out of 139 no longer rewrites/snapshots/logs the
#     other 137 untouched ones. Tested against a live server before this
#     was shipped: re-uploading a completely unchanged zip took ZERO
#     backups and wrote ZERO files; a zip with 2 real changes out of 139
#     entries wrote exactly those 2, logged "2 changed ... 137 already
#     matched", and took exactly one backup snapshot (not zero, not 139).
#
# No database migration in this push.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app/blueprints/dev_files.py app/templates/dev_files run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run push_dev_files.sh and push_dev_files_expand_scope.sh first, then this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS/templates/dev_files"
cp app/blueprints/dev_files.py "backups/$TS/dev_files.py.bak" 2>/dev/null || true
cp app/templates/dev_files/index.html "backups/$TS/templates/dev_files/index.html.bak" 2>/dev/null || true
echo "==> Backed up existing files to backups/$TS/"

echo "==> Writing app/blueprints/dev_files.py"
base64 -d > app/blueprints/dev_files.py << 'DEV_FILES_PY_B64'

DEV_FILES_PY_B64

echo "==> Writing app/templates/dev_files/index.html"
base64 -d > app/templates/dev_files/index.html << 'DEV_INDEX_HTML_B64'

DEV_INDEX_HTML_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/blueprints/dev_files.py').read())"
echo "    syntax OK"

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Dev Files: file list is now grouped by folder (collapsible), with a"
echo "filter box up top. Zip upload now only touches files that actually"
echo "changed - everything else is left alone, unbacked-up, unlogged."
echo "==================================================================="
